import React, { useCallback } from 'react';
import { createEnhancedTooltip } from '../utils/tooltipHelpers';
import { sources } from '../../data/sources';
import airlines from '../../data/airlines_full';

const AvailabilityBadges = ({ 
  route, 
  dateString, 
  classData, 
  classesToShow,
  activeTooltipRef,
  cellPages,
  handlePageChange,
  getEnrichedFlightData,
  getFilteredFlightData,
  currentFilters = {},
}) => {
  const ITEMS_PER_PAGE = 3;

  const handleBadgeClick = useCallback((e, classCode) => {
    e.stopPropagation();

    // If a tooltip is already active, remove it
    if (activeTooltipRef.current) {
      const existingTooltip = document.getElementById(activeTooltipRef.current);
      if (existingTooltip) {
        document.body.removeChild(existingTooltip);
      }
    }

    // Process the badge click and show tooltip with filtered flights

    try {
      // Get filtered flight data for the tooltip
      const flights = getFilteredFlightData(route, classCode, dateString, classData, currentFilters);

      if (!flights || flights.length === 0) {

        // Show a hyphen badge if no flights after applying filters
        const badge = document.createElement('div');
        badge.className = 'flight-tooltip empty-tooltip';
        badge.id = `tooltip-${route}-${dateString}-${classCode}`;
        badge.style.position = 'absolute';
        badge.style.zIndex = '1000';
        badge.style.backgroundColor = 'white';
        badge.style.border = '1px solid #ccc';
        badge.style.borderRadius = '4px';
        badge.style.padding = '10px';
        badge.style.boxShadow = '0 2px 8px rgba(0, 0, 0, 0.15)';

        const content = document.createElement('div');
        content.textContent = 'No flights available with current filters';
        badge.appendChild(content);

        document.body.appendChild(badge);

        // Set positioning
        const rect = e.currentTarget.getBoundingClientRect();
        badge.style.left = `${rect.left}px`;
        badge.style.top = `${rect.bottom + window.scrollY + 5}px`;

        // Update active tooltip ref
        activeTooltipRef.current = badge.id;

        return;
      }

      // Create enhanced tooltip
      const tooltip = createEnhancedTooltip(classCode, flights, route, dateString, sources, airlines);
      if (!tooltip) return;

      // Set positioning relative to the clicked badge
      const rect = e.currentTarget.getBoundingClientRect();
      tooltip.style.left = `${rect.left}px`;
      tooltip.style.top = `${rect.bottom + window.scrollY + 5}px`;

      // Update active tooltip ref
      activeTooltipRef.current = tooltip.id;
    } catch (error) {
      console.error('Error filtering flights for tooltip:', error);
      return;
    }
  }, [route, dateString, classData, getFilteredFlightData, activeTooltipRef, currentFilters]);

  // Only show a subset of classes based on pagination
  const currentPage = cellPages[dateString] || 0;
  const startIdx = currentPage * ITEMS_PER_PAGE;
  const endIdx = startIdx + ITEMS_PER_PAGE;
  const visibleClasses = classesToShow.slice(startIdx, endIdx);

  return (
    <div className="badge-container">
      <div className="availability-badges">
        {visibleClasses.map(classCode => {
          const available = classData[`${classCode}Available`];
          const direct = classData[`${classCode}Direct`];
          const airlines = classData[`${classCode}Airlines`] || '';
          const mileageCost = classData[`${classCode}MileageCost`];

          return (
            <div 
              key={classCode}
              className={`availability-badge ${available ? 'available' : 'unavailable'} class-${classCode}`}
              onClick={(e) => handleBadgeClick(e, classCode)}
            >
              <div className="badge-content">
                <div className="badge-class">{classCode}</div>
                {available && (
                  <div className="badge-info">
                    {direct && <span className="direct-indicator">●</span>}
                    {mileageCost && <span className="points">{Number(mileageCost).toLocaleString()}</span>}
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* Pagination controls if there are more than ITEMS_PER_PAGE classes */}
      {classesToShow.length > ITEMS_PER_PAGE && (
        <div className="badge-pagination">
          <button 
            className="page-btn prev"
            onClick={(e) => handlePageChange(dateString, 'prev', e)}
            disabled={currentPage === 0}
          >
            &lt;
          </button>
          <button 
            className="page-btn next"
            onClick={(e) => handlePageChange(dateString, 'next', e)}
            disabled={(currentPage + 1) * ITEMS_PER_PAGE >= classesToShow.length}
          >
            &gt;
          </button>
        </div>
      )}
    </div>
  );
};

export default AvailabilityBadges;
